//! Bounded recursive sidecar lookup, ID3 USLT and Vorbis-comment lyric extraction.
use std::{path::{Path,PathBuf},collections::HashSet,io::Read};
use lyric_core::{models::*,identity::{normalized,artists,rate}};
pub struct LocalLibrary{roots:Vec<PathBuf>}
impl LocalLibrary{
 pub fn new(roots:Vec<String>)->Self{Self{roots:roots.into_iter().map(PathBuf::from).collect()}}
 pub fn get(&self,track:&Track)->Option<Lyrics>{
  let mut paths=Vec::new();let mut pending=self.roots.iter().map(|p|(p.clone(),0)).collect::<Vec<_>>();let mut seen=HashSet::new();
  while let Some((dir,depth))=pending.pop(){if paths.len()>=20000||depth>12{continue}let Ok(canonical)=dir.canonicalize()else{continue};if !seen.insert(canonical){continue}let Ok(entries)=std::fs::read_dir(dir)else{continue};for e in entries.flatten(){let Ok(kind)=e.file_type()else{continue};if kind.is_symlink(){continue}let p=e.path();if kind.is_dir(){pending.push((p,depth+1))}else if kind.is_file(){paths.push(p)}if paths.len()>=20000{break}}}
  let mut ranked=paths.into_iter().filter_map(|p|{let extension=p.extension()?.to_str()?.to_ascii_lowercase();let supported=["lrc","qrc","krc","yrc","ttml","txt","mp3","flac","ogg","opus"].contains(&extension.as_str());if !supported{return None}let name=p.file_stem()?.to_string_lossy();let exact=normalized(&name)==normalized(&track.title);let score=if exact{if track.artist.is_empty()||p.parent().is_some_and(|p|normalized(&p.to_string_lossy()).contains(&normalized(&track.artist))){100}else{88}}else{let (a,b)=name.split_once(" - ")?;let hit=|title:&str,artist:&str|Hit{provider:Provider::new("Local"),id:String::new(),title:title.into(),artists:artists(artist),album:String::new(),duration:track.duration,extra:Default::default()};rate(track,&hit(b,a)).or_else(||rate(track,&hit(a,b)))?};Some((score,p,extension))}).collect::<Vec<_>>();ranked.sort_by(|a,b|b.0.cmp(&a.0).then_with(||a.1.cmp(&b.1)));
  for(_,path,extension)in ranked.into_iter().take(24){let Some(text)=read_lyric(&path,&extension)else{continue};let format=match extension.as_str(){"qrc"=>Format::Qrc,"krc"=>Format::Krc,"yrc"=>Format::Yrc,"ttml"=>Format::Ttml,"txt"=>Format::Text,_=>Format::Lrc};let format=if format==Format::Lrc&&!text.contains('['){Format::Text}else{format};if let Ok(l)=crate::formats::parse(&Payload{format,original:text,translation:String::new(),instrumental:false}){if l.usable(){return Some(l)}}}
  None
 }
}
fn decode(bytes:&[u8])->String{if bytes.starts_with(&[0xff,0xfe])||bytes.starts_with(&[0xfe,0xff]){let little=bytes[0]==0xff;return String::from_utf16_lossy(&bytes[2..].chunks_exact(2).map(|b|if little{u16::from_le_bytes([b[0],b[1]])}else{u16::from_be_bytes([b[0],b[1]])}).collect::<Vec<_>>())}if let Ok(s)=std::str::from_utf8(bytes){return s.trim_start_matches('\u{feff}').into()}#[cfg(feature="gbk")]{encoding_rs::GBK.decode(bytes).0.into_owned()}#[cfg(not(feature="gbk"))]{String::from_utf8_lossy(bytes).into_owned()}}
fn read_lyric(path:&Path,ext:&str)->Option<String>{let mut bytes=Vec::new();std::fs::File::open(path).ok()?.take(16*1024*1024+1).read_to_end(&mut bytes).ok()?;let media=matches!(ext,"mp3"|"flac"|"ogg"|"opus");if bytes.len()>16*1024*1024{if !media{return None}bytes.truncate(16*1024*1024);}match ext{"krc"=>crate::crypto::krc_text(&bytes).ok(),"mp3"=>id3(&bytes),"flac"|"ogg"|"opus"=>vorbis(&bytes),_=>Some(decode(&bytes))}}
fn synchsafe(b:&[u8])->Option<usize>{if b.len()!=4||b.iter().any(|b|b&128!=0){return None}Some(b.iter().fold(0,|n,b|(n<<7)|*b as usize))}
fn id3(bytes:&[u8])->Option<String>{if bytes.get(..3)?!=b"ID3"{return None}let v=*bytes.get(3)?;if v!=3&&v!=4{return None}let end=10+synchsafe(bytes.get(6..10)?)?;let tag=bytes.get(10..end)?;let mut at=0;while at+10<=tag.len(){let id=&tag[at..at+4];let size=if v==4{synchsafe(&tag[at+4..at+8])?}else{u32::from_be_bytes(tag[at+4..at+8].try_into().ok()?)as usize};let body=tag.get(at+10..at+10+size)?;if id==b"USLT"&&body.len()>4{let enc=body[0];let text=&body[4..];let start=if enc==1||enc==2{text.chunks_exact(2).position(|b|b==[0,0]).map(|p|(p+1)*2)?}else{text.iter().position(|b|*b==0)?+1};let content=&text[start..];return Some(if enc==0{content.iter().map(|b|char::from(*b)).collect()}else if enc==2{String::from_utf16_lossy(&content.chunks_exact(2).map(|b|u16::from_be_bytes([b[0],b[1]])).collect::<Vec<_>>())}else{decode(content)})}at=at.checked_add(10+size)?;}None}
fn vorbis(bytes:&[u8])->Option<String>{
 // A comment's little-endian length immediately precedes KEY=value in FLAC/Vorbis/Opus.
 for key in [b"LYRICS=".as_slice(),b"SYNCEDLYRICS=",b"UNSYNCEDLYRICS="]{for (at,_)in bytes.windows(key.len()).enumerate().filter(|(_,b)|b.eq_ignore_ascii_case(key)){if at<4{continue}let size=u32::from_le_bytes(bytes[at-4..at].try_into().ok()?)as usize;if size<key.len()||size>8*1024*1024{continue}if let Some(body)=bytes.get(at+key.len()..at+size){return Some(decode(body))}}}None
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn large_audio_keeps_bounded_header_lyrics(){use std::io::Write;let p=std::env::temp_dir().join(format!("dotisle-large-header-{}.flac",std::process::id()));let mut file=std::fs::File::create(&p).unwrap();let text=b"LYRICS=[00:03.75]Header lyric";file.write_all(b"fLaC").unwrap();file.write_all(&(text.len()as u32).to_le_bytes()).unwrap();file.write_all(text).unwrap();file.set_len(20*1024*1024).unwrap();drop(file);assert_eq!(read_lyric(&p,"flac").as_deref(),Some("[00:03.75]Header lyric"));assert!(read_lyric(&p,"lrc").is_none());std::fs::remove_file(p).unwrap();}
 #[test]fn vorbis_respects_declared_comment_length(){let text=b"[00:01.25]hello";let mut bytes=((7+text.len())as u32).to_le_bytes().to_vec();bytes.extend(b"LYRICS=");bytes.extend(text);bytes.extend(b"outside");assert_eq!(vorbis(&bytes).as_deref(),Some("[00:01.25]hello"));bytes[0]=255;assert!(vorbis(&bytes).is_none());}
 #[test]fn local_sidecar_matches_artist_filename_and_utf16(){let dir=std::env::temp_dir().join(format!("dotisle-local-{}",std::process::id()));std::fs::create_dir_all(&dir).unwrap();let path=dir.join("织梦者 - 晨雾.lrc");let mut bytes=vec![255,254];for c in "[00:04.50]晨雾散去".encode_utf16(){bytes.extend(c.to_le_bytes())}std::fs::write(&path,bytes).unwrap();let t=Track::new("a","晨雾","织梦者","","Local",std::time::Duration::ZERO);let l=LocalLibrary::new(vec![dir.to_string_lossy().into_owned()]).get(&t).unwrap();assert_eq!(l.lines[0].at,4500);assert_eq!(l.lines[0].text,"晨雾散去");let _=std::fs::remove_file(path);let _=std::fs::remove_dir(dir);}
}
